package com.mycompany.rentalmanagement.servlet;
import com.mycompany.rentalmanagement.dao.UserDAO;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.SQLException;import java.util.Map;
@WebServlet("/login") public class LoginServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/login.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{Map<String,String> u=new UserDAO().authenticate(r.getParameter("username"),r.getParameter("password"));if(u==null){r.setAttribute("error","Invalid username or password.");doGet(r,s);return;}r.getSession(true).setAttribute("user",u);s.sendRedirect(r.getContextPath()+"/dashboard");}catch(SQLException e){r.setAttribute("error","Database connection failed. Check MySQL and database/README setup.");doGet(r,s);}}}
